-- The sign-in service (services/control-plane): Better Auth's OAuth 2.1 / OIDC provider and key tables,
-- generated by `npx auth generate --config auth.cli.ts` against 0001-0008 (so they reference users and auth_sessions),
-- plus the least-privilege role the service runs as and the desktop app's client row.
--
-- ao_auth can do what sign-in needs and nothing else: read and write people and their sign-in rows, but not
-- delete a user, not change a role or status, and not touch sync data, credits, coupons or the audit log.
-- Row-level security is on for the tables that have it, with a policy that lets this one role through.
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'ao_auth') THEN CREATE ROLE ao_auth LOGIN; END IF;
END $$;

create table "jwks" ("id" text not null primary key, "publicKey" text not null, "privateKey" text not null, "createdAt" timestamptz not null, "expiresAt" timestamptz, "alg" text, "crv" text);

create table "oauthClient" ("id" text not null primary key, "clientId" text not null unique, "clientSecret" text, "clientDiscoveryId" text, "disabled" boolean, "skipConsent" boolean, "enableEndSession" boolean, "subjectType" text, "scopes" jsonb, "clientCredentialsScopes" jsonb, "userId" text references "users" ("id") on delete cascade, "createdAt" timestamptz, "updatedAt" timestamptz, "name" text, "uri" text, "icon" text, "contacts" jsonb, "tos" text, "policy" text, "softwareId" text, "softwareVersion" text, "softwareStatement" text, "redirectUris" jsonb not null, "postLogoutRedirectUris" jsonb, "backchannelLogoutUri" text, "backchannelLogoutSessionRequired" boolean, "tokenEndpointAuthMethod" text, "applicationType" text, "jwks" text, "jwksUri" text, "grantTypes" jsonb, "responseTypes" jsonb, "requirePKCE" boolean, "dpopBoundAccessTokens" boolean, "referenceId" text, "metadata" jsonb);

create table "oauthResource" ("id" text not null primary key, "identifier" text not null unique, "name" text not null, "accessTokenTtl" integer, "refreshTokenTtl" integer, "signingAlgorithm" text, "signingKeyId" text, "allowedScopes" jsonb, "customClaims" jsonb, "dpopBoundAccessTokensRequired" boolean, "disabled" boolean, "createdAt" timestamptz, "updatedAt" timestamptz, "policyVersion" integer, "metadata" jsonb);

create table "oauthClientResource" ("id" text not null primary key, "clientId" text not null references "oauthClient" ("clientId") on delete cascade, "resourceId" text not null references "oauthResource" ("identifier") on delete cascade, "metadata" jsonb, "createdAt" timestamptz);

create table "oauthRefreshToken" ("id" text not null primary key, "token" text not null unique, "clientId" text not null references "oauthClient" ("clientId") on delete cascade, "sessionId" text references "auth_sessions" ("id") on delete set null, "userId" text not null references "users" ("id") on delete cascade, "referenceId" text, "authorizationCodeId" text, "resources" jsonb, "requestedUserInfoClaims" jsonb, "expiresAt" timestamptz not null, "createdAt" timestamptz not null, "revoked" timestamptz, "rotatedAt" timestamptz, "rotationReplayResponse" text, "rotationReplayExpiresAt" timestamptz, "authTime" timestamptz, "confirmation" jsonb, "scopes" jsonb not null);

create table "oauthAccessToken" ("id" text not null primary key, "token" text not null unique, "clientId" text not null references "oauthClient" ("clientId") on delete cascade, "sessionId" text references "auth_sessions" ("id") on delete set null, "userId" text references "users" ("id") on delete cascade, "referenceId" text, "authorizationCodeId" text, "resources" jsonb, "requestedUserInfoClaims" jsonb, "refreshId" text references "oauthRefreshToken" ("id") on delete cascade, "expiresAt" timestamptz not null, "createdAt" timestamptz not null, "revoked" timestamptz, "confirmation" jsonb, "scopes" jsonb not null);

create table "oauthConsent" ("id" text not null primary key, "clientId" text not null references "oauthClient" ("clientId") on delete cascade, "userId" text references "users" ("id") on delete cascade, "referenceId" text, "resources" jsonb, "requestedUserInfoClaims" jsonb, "scopes" jsonb not null, "createdAt" timestamptz not null, "updatedAt" timestamptz not null);

create table "oauthClientAssertion" ("id" text not null primary key, "expiresAt" timestamptz not null);

create index "oauthClient_userId_idx" on "oauthClient" ("userId");

create index "oauthClientResource_clientId_idx" on "oauthClientResource" ("clientId");

create index "oauthClientResource_resourceId_idx" on "oauthClientResource" ("resourceId");

create index "oauthRefreshToken_clientId_idx" on "oauthRefreshToken" ("clientId");

create index "oauthRefreshToken_sessionId_idx" on "oauthRefreshToken" ("sessionId");

create index "oauthRefreshToken_userId_idx" on "oauthRefreshToken" ("userId");

create index "oauthRefreshToken_authorizationCodeId_idx" on "oauthRefreshToken" ("authorizationCodeId");

create index "oauthAccessToken_clientId_idx" on "oauthAccessToken" ("clientId");

create index "oauthAccessToken_sessionId_idx" on "oauthAccessToken" ("sessionId");

create index "oauthAccessToken_userId_idx" on "oauthAccessToken" ("userId");

create index "oauthAccessToken_authorizationCodeId_idx" on "oauthAccessToken" ("authorizationCodeId");

create index "oauthAccessToken_refreshId_idx" on "oauthAccessToken" ("refreshId");

create index "oauthConsent_clientId_idx" on "oauthConsent" ("clientId");

create index "oauthConsent_userId_idx" on "oauthConsent" ("userId");

create unique index "oauthClientResource_clientId_resourceId_uidx" on "oauthClientResource" ("clientId", "resourceId");

-- access for ao_auth
GRANT USAGE ON SCHEMA public TO ao_auth;
GRANT SELECT, INSERT ON users TO ao_auth;
GRANT UPDATE (email, display_name, avatar_url, email_verified, updated_at, last_active_at) ON users TO ao_auth;
CREATE POLICY auth_service ON users TO ao_auth USING (true) WITH CHECK (true);
GRANT SELECT, INSERT, UPDATE, DELETE ON auth_accounts, auth_sessions, auth_verifications TO ao_auth;
CREATE POLICY auth_service ON auth_accounts TO ao_auth USING (true) WITH CHECK (true);
CREATE POLICY auth_service ON auth_sessions TO ao_auth USING (true) WITH CHECK (true);
CREATE POLICY auth_service ON auth_verifications TO ao_auth USING (true) WITH CHECK (true);
GRANT SELECT, INSERT, UPDATE, DELETE ON jwks, "oauthClient", "oauthResource", "oauthClientResource", "oauthRefreshToken", "oauthAccessToken", "oauthConsent", "oauthClientAssertion" TO ao_auth;
-- The admin views read these (no secrets): clients and consents.
GRANT SELECT ON "oauthClient", "oauthConsent" TO ao_readonly;
GRANT SELECT ON "oauthClient", "oauthConsent", "oauthRefreshToken", "oauthAccessToken" TO ao_admin;
GRANT DELETE ON "oauthRefreshToken", "oauthAccessToken" TO ao_admin;          -- "sign this user out everywhere" revokes their tokens

-- the desktop app: a public client (no secret), PKCE required, loopback redirect on any port (RFC 8252),
-- first-party so there is no consent screen.
INSERT INTO "oauthClient" (id, "clientId", name, "redirectUris", "tokenEndpointAuthMethod", "applicationType", "grantTypes", "responseTypes",
                           "requirePKCE", "skipConsent", scopes, disabled, "createdAt", "updatedAt")
VALUES ('oc_agentic_office_desktop', 'agentic-office-desktop', 'Agentic Office', '["http://127.0.0.1/callback"]', 'none', 'native',
        '["authorization_code","refresh_token"]', '["code"]', true, true, '["openid","profile","email","offline_access"]', false, now(), now());
